  static readonly Name = EXIT_PLAN_MODE_TOOL_NAME;

  constructor(
    private config: Config,
    messageBus: MessageBus,
  ) {
    const definition = getExitPlanModeDefinition();
    super(
      ExitPlanModeTool.Name,
      'Exit Plan Mode',
      definition.base.description!,
      Kind.Plan,
      definition.base.parametersJsonSchema,
      messageBus,
    );
  }

  protected override validateToolParamValues(
    params: ExitPlanModeParams,
  ): string | null {
    if (!params.plan_filename || params.plan_filename.trim() === '') {
      return 'plan_filename is required.';
    }

    // Only a plain filename is accepted. Resolve the full path internally
    // against the designated plans directory using the basename so that any
    // directory components in the input are stripped.
    const plansDir = this.config.storage.getPlansDir();
    const resolvedPath = path.join(
      plansDir,
      path.basename(params.plan_filename),
